const SIZE=15, EMPTY=0, BLACK=1, WHITE=2;
const canvas=document.getElementById('board'),ctx=canvas.getContext('2d');
const $=id=>document.getElementById(id);
const saved=JSON.parse(localStorage.getItem('gomoku-settings')||'{}');
let mode=saved.mode||'ai',difficulty=saved.difficulty||'normal',humanColor=saved.humanColor||BLACK;
let board,moves,current,gameOver=false,thinking=false,winLine=null;
let score=JSON.parse(localStorage.getItem('gomoku-score')||'{"black":0,"white":0,"draw":0}');
let soundOn=saved.soundOn!==false;

function persist(){localStorage.setItem('gomoku-settings',JSON.stringify({mode,difficulty,humanColor,soundOn,theme:document.body.classList.contains('dark')?'dark':'light'}))}
function resetBoard(){board=Array.from({length:SIZE},()=>Array(SIZE).fill(EMPTY));moves=[];current=BLACK;gameOver=false;thinking=false;winLine=null;$('gameResult').hidden=true;updateUI();draw();if(mode==='ai'&&humanColor===WHITE)setTimeout(aiMove,450)}
function startNew(){resetBoard();}
function resize(){const dpr=Math.min(devicePixelRatio||1,2),size=canvas.clientWidth;canvas.width=size*dpr;canvas.height=size*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);draw()}
function metrics(){const size=canvas.clientWidth,pad=size*.055,cell=(size-pad*2)/(SIZE-1);return{size,pad,cell}}
function draw(){if(!board)return;const{size,pad,cell}=metrics();ctx.clearRect(0,0,size,size);ctx.strokeStyle='rgba(63,38,14,.68)';ctx.lineWidth=1;for(let i=0;i<SIZE;i++){let p=pad+i*cell;ctx.beginPath();ctx.moveTo(pad,p);ctx.lineTo(size-pad,p);ctx.stroke();ctx.beginPath();ctx.moveTo(p,pad);ctx.lineTo(p,size-pad);ctx.stroke()}[[3,3],[11,3],[7,7],[3,11],[11,11]].forEach(([x,y])=>{ctx.beginPath();ctx.arc(pad+x*cell,pad+y*cell,Math.max(2,cell*.08),0,Math.PI*2);ctx.fillStyle='#5c3516';ctx.fill()});moves.forEach((m,i)=>drawStone(m.x,m.y,m.color,i===moves.length-1));if(winLine){ctx.beginPath();ctx.moveTo(pad+winLine[0].x*cell,pad+winLine[0].y*cell);ctx.lineTo(pad+winLine[4].x*cell,pad+winLine[4].y*cell);ctx.strokeStyle='#d84c35';ctx.lineWidth=Math.max(3,cell*.09);ctx.stroke()}}
function drawStone(x,y,color,last){const{pad,cell}=metrics(),cx=pad+x*cell,cy=pad+y*cell,r=cell*.4,g=ctx.createRadialGradient(cx-r*.35,cy-r*.4,r*.08,cx,cy,r);if(color===BLACK){g.addColorStop(0,'#696969');g.addColorStop(.4,'#262626');g.addColorStop(1,'#050505')}else{g.addColorStop(0,'#fff');g.addColorStop(.55,'#eeeae1');g.addColorStop(1,'#aaa295')}ctx.save();ctx.shadowColor='rgba(30,20,10,.38)';ctx.shadowBlur=r*.35;ctx.shadowOffsetY=r*.2;ctx.beginPath();ctx.arc(cx,cy,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();ctx.restore();if(last){ctx.beginPath();ctx.arc(cx,cy,r*.16,0,Math.PI*2);ctx.fillStyle=color===BLACK?'#e7d9bd':'#c6432d';ctx.fill()}}
function place(x,y){if(gameOver||thinking||board[y][x]!==EMPTY)return false;board[y][x]=current;moves.push({x,y,color:current});tone(current);const line=getWin(x,y,current);if(line){winLine=line;finish(current)}else if(moves.length===SIZE*SIZE)finish(EMPTY);else{current=current===BLACK?WHITE:BLACK;updateUI();draw()}return true}
function getWin(x,y,color){for(const[dX,dY]of[[1,0],[0,1],[1,1],[1,-1]]){const line=[{x,y}];for(const sign of[-1,1])for(let n=1;n<5;n++){let nx=x+dX*n*sign,ny=y+dY*n*sign;if(nx<0||ny<0||nx>=SIZE||ny>=SIZE||board[ny][nx]!==color)break;sign<0?line.unshift({x:nx,y:ny}):line.push({x:nx,y:ny})}if(line.length>=5)return line.slice(0,5)}return null}
function finish(winner){gameOver=true;if(winner===BLACK)score.black++;else if(winner===WHITE)score.white++;else score.draw++;localStorage.setItem('gomoku-score',JSON.stringify(score));updateScore();draw();setTimeout(()=>{const name=winner===BLACK?'黑方':winner===WHITE?'白方':'平局';$('resultStone').className='result-stone '+(winner===BLACK?'black':winner===WHITE?'white':'');$('resultTitle').textContent=winner?name+'胜':'势均力敌';$('resultMessage').textContent=winner?'漂亮的五子连珠':'棋盘已满，握手言和';$('gameResult').hidden=false},450)}
function updateUI(){const name=current===BLACK?'黑方落子':'白方落子';$('turnText').textContent=thinking?'AI 正在思考':name;$('turnStone').className='status-stone '+(current===BLACK?'black':'white');$('moveCount').textContent=String(moves?.length||0).padStart(2,'0');$('undoButton').disabled=!moves?.length||thinking||gameOver;document.querySelectorAll('#modeSelector button').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));document.querySelectorAll('#difficultySelector button').forEach(b=>b.classList.toggle('active',b.dataset.level===difficulty));document.querySelectorAll('#colorSelector button').forEach(b=>b.classList.toggle('active',(b.dataset.color==='black'?BLACK:WHITE)===humanColor));$('difficultyField').hidden=mode!=='ai';$('colorField').hidden=mode!=='ai'}
function updateScore(){$('blackWins').textContent=score.black||0;$('whiteWins').textContent=score.white||0;$('draws').textContent=score.draw||0}
function aiMove(){if(gameOver||mode!=='ai'||current===humanColor)return;thinking=true;updateUI();setTimeout(()=>{const move=chooseMove();thinking=false;if(move)place(move.x,move.y)},difficulty==='hard'?430:280)}
function chooseMove(){if(!moves.length)return{x:7,y:7};let candidates=[];for(let y=0;y<SIZE;y++)for(let x=0;x<SIZE;x++)if(board[y][x]===EMPTY&&hasNeighbor(x,y,2)){let attack=scorePoint(x,y,current),defend=scorePoint(x,y,current===BLACK?WHITE:BLACK);let value=Math.max(attack,defend*(difficulty==='easy'?.78:1.04))+attack*.12+Math.random()*(difficulty==='easy'?800:25);candidates.push({x,y,value})}candidates.sort((a,b)=>b.value-a.value);if(difficulty==='easy'&&candidates.length>3)return candidates[Math.floor(Math.random()*Math.min(7,candidates.length))];return candidates[0]}
function hasNeighbor(x,y,r){for(let dy=-r;dy<=r;dy++)for(let dx=-r;dx<=r;dx++){let nx=x+dx,ny=y+dy;if(nx>=0&&ny>=0&&nx<SIZE&&ny<SIZE&&board[ny][nx]!==EMPTY)return true}return false}
function scorePoint(x,y,color){let total=0;for(const[dx,dy]of[[1,0],[0,1],[1,1],[1,-1]]){let count=1,open=0;for(const sign of[-1,1]){for(let n=1;n<5;n++){let nx=x+dx*n*sign,ny=y+dy*n*sign;if(nx<0||ny<0||nx>=SIZE||ny>=SIZE)break;if(board[ny][nx]===color)count++;else{if(board[ny][nx]===EMPTY)open++;break}}}if(count>=5)total+=1000000;else if(count===4&&open===2)total+=120000;else if(count===4)total+=25000;else if(count===3&&open===2)total+=9000;else if(count===3)total+=1400;else if(count===2&&open===2)total+=500;else total+=count*15}return total}
function undo(){if(!moves.length||thinking)return;$('gameResult').hidden=true;gameOver=false;winLine=null;let n=mode==='ai'?Math.min(2,moves.length):1;while(n--){const m=moves.pop();board[m.y][m.x]=EMPTY}current=moves.length%2===0?BLACK:WHITE;updateUI();draw()}
function tone(color){if(!soundOn)return;try{const ac=new(window.AudioContext||window.webkitAudioContext)(),o=ac.createOscillator(),g=ac.createGain();o.frequency.value=color===BLACK?180:230;o.type='sine';g.gain.setValueAtTime(.07,ac.currentTime);g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+.08);o.connect(g);g.connect(ac.destination);o.start();o.stop(ac.currentTime+.08)}catch{}}
canvas.addEventListener('pointerup',e=>{if(mode==='ai'&&current!==humanColor)return;const r=canvas.getBoundingClientRect(),{pad,cell}=metrics(),x=Math.round((e.clientX-r.left-pad)/cell),y=Math.round((e.clientY-r.top-pad)/cell);if(x>=0&&y>=0&&x<SIZE&&y<SIZE&&place(x,y)&&mode==='ai'&&!gameOver)setTimeout(aiMove,100)});
$('modeSelector').onclick=e=>{if(e.target.dataset.mode){mode=e.target.dataset.mode;persist();resetBoard()}};
$('difficultySelector').onclick=e=>{if(e.target.dataset.level){difficulty=e.target.dataset.level;persist();updateUI()}};
$('colorSelector').onclick=e=>{const b=e.target.closest('button');if(b){humanColor=b.dataset.color==='black'?BLACK:WHITE;persist();resetBoard()}};
$('newGameButton').onclick=startNew;$('restartButton').onclick=startNew;$('playAgainButton').onclick=startNew;$('undoButton').onclick=undo;
$('resetScoreButton').onclick=()=>{score={black:0,white:0,draw:0};localStorage.setItem('gomoku-score',JSON.stringify(score));updateScore()};
$('soundButton').onclick=()=>{soundOn=!soundOn;$('soundButton').textContent=soundOn?'♪':'×';persist()};
$('themeButton').onclick=()=>{document.body.classList.toggle('dark');$('themeButton').textContent=document.body.classList.contains('dark')?'☀':'☾';persist();draw()};
if(saved.theme==='dark')document.body.classList.add('dark');$('themeButton').textContent=document.body.classList.contains('dark')?'☀':'☾';$('soundButton').textContent=soundOn?'♪':'×';
window.addEventListener('resize',resize);updateScore();resetBoard();requestAnimationFrame(resize);
